const body=$json.body||$json;
for(const key of ['run_id','account_id','company','score']) if(!body[key]) throw new Error(`Missing ${key}`);
if($vars.N8N_WEBHOOK_SECRET && $json.headers?.['x-workflow-secret']!==$vars.N8N_WEBHOOK_SECRET) throw new Error('Invalid workflow secret');
if(!['qualified','review'].includes(body.score?.tier)) return [{json:{...body,skip_contacts:true,skip_reason:`Tier ${body.score?.tier} is not eligible`,evaluation_mode:false}}];
return [{json:{...body,evaluation_mode:false}}];

const people=($json.people||[]).slice(0,8);
const details=people.map(person=>({id:person.id,first_name:person.first_name,last_name:person.last_name,name:person.name,linkedin_url:person.linkedin_url,organization_name:person.organization?.name,domain:$('Validate Research Result').item.json.domain}));
return [{json:{...$('Validate Research Result').item.json,search_candidates:people,enrichment_details:details}}];

const ctx=$('Bound Apollo Candidates').item.json;
const enriched=$json.matches||$json.people||[];
const byId=new Map(enriched.map(person=>[person.id,person]));
const candidates=(ctx.search_candidates||[]).map(person=>{const e=byId.get(person.id)||{}; return {apollo_person_id:person.id,full_name:e.name||person.name||`${person.first_name||''} ${person.last_name||''}`.trim(),title:e.title||person.title||'',seniority:e.seniority||person.seniority||'',departments:e.departments||person.departments||[],linkedin_url:e.linkedin_url||person.linkedin_url||null,work_email:e.email_status==='verified'?e.email:null,email_status:e.email_status==='verified'?'verified':e.email?'unverified':'unavailable'};});
const apollo_status=!candidates.length?'no_match':enriched.length?'enriched':'search_only';
return [{json:{...ctx,candidates,apollo_status}}];

