const context=$('Prepare Committee Agent Input').item.json;
let result;
try {const raw=$json.output??$json; result=typeof raw==='string'?JSON.parse(raw):raw;} catch {return [{json:{...context,contacts:[],committee_valid:false,validation_errors:['Invalid agent JSON'],status:'failed_partial'}}];}
const source=new Map((context.candidates||[]).map(c=>[String(c.apollo_person_id),c]));
const clamp=v=>Math.max(0,Math.min(100,Number(v)||0));
const errors=[];
const contacts=(result.candidates||[]).filter(c=>{if(!source.has(String(c.apollo_person_id))){errors.push(`Invented Apollo ID: ${c.apollo_person_id}`);return false;}return true;}).map(c=>{const original=source.get(String(c.apollo_person_id)); const components={role_relevance:clamp(c.role_relevance),decision_authority:clamp(c.decision_authority),pain_alignment:clamp(c.pain_alignment),historical_performance:clamp(c.historical_performance),data_confidence:clamp(c.data_confidence)}; const total=Math.round(components.role_relevance*.40+components.decision_authority*.25+components.pain_alignment*.20+components.historical_performance*.10+components.data_confidence*.05); return {...original,...c,...components,total,activation_eligible:original.email_status==='verified'};}).sort((a,b)=>b.total-a.total).slice(0,5).map((c,index)=>({...c,rank:index+1}));
if(contacts.length<3) errors.push('Fewer than three credible contacts');
if(contacts.length>5) errors.push('More than five contacts');
return [{json:{...context,contacts,committee_valid:errors.length===0,validation_errors:errors,needs_review:Boolean(result.needs_review||errors.length),review_reason:result.review_reason||errors.join('; ')||null,status:errors.length?'failed_partial':'completed',intermediateSteps:$json.intermediateSteps||[]}}];
